using System.Globalization;
using Saldo360.Application.Workspaces;
using Saldo360.Domain.Common;
using Saldo360.Domain.Goals;

namespace Saldo360.Application.Goals;

public sealed class FinancialGoalService(IFinancialWorkspaceRepository workspaces, IFinancialGoalRepository repository, TimeProvider time)
{
    public async Task<FinancialGoalResult> CreateAsync(Guid workspaceId, Guid userId, FinancialGoalInput input, CancellationToken ct)
    { if (!await Member(workspaceId,userId,ct)) return new(FinancialGoalAccess.NotFound,null,null); var (d,e)=Validate(input); if(d is null)return new(FinancialGoalAccess.Invalid,null,e); var g=FinancialGoal.Create(workspaceId,d,time.GetUtcNow()); await repository.AddAsync(g,ct); return new(FinancialGoalAccess.Allowed,await repository.GetAsync(workspaceId,g.Id,ct),null); }
    public async Task<FinancialGoalDto?> GetAsync(Guid workspaceId,Guid id,Guid userId,CancellationToken ct)=>await Member(workspaceId,userId,ct)?await repository.GetAsync(workspaceId,id,ct):null;
    public async Task<(IReadOnlyList<FinancialGoalDto>? Items,bool NotFound)> ListAsync(Guid workspaceId,Guid userId,bool includeArchived,CancellationToken ct)=>!await Member(workspaceId,userId,ct)?(null,true):(await repository.ListAsync(workspaceId,includeArchived,ct),false);
    public async Task<FinancialGoalResult> UpdateAsync(Guid workspaceId,Guid id,Guid userId,FinancialGoalInput input,CancellationToken ct){if(!await Member(workspaceId,userId,ct))return new(FinancialGoalAccess.NotFound,null,null);var g=await repository.FindAsync(workspaceId,id,ct);if(g is null)return new(FinancialGoalAccess.NotFound,null,null);var(d,e)=Validate(input);if(d is null)return new(FinancialGoalAccess.Invalid,null,e);try{g.Update(d,time.GetUtcNow());await repository.SaveAsync(ct);return new(FinancialGoalAccess.Allowed,await repository.GetAsync(workspaceId,id,ct),null);}catch(InvalidOperationException ex){return new(FinancialGoalAccess.Conflict,null,null,ex.Message);}}
    public async Task<FinancialGoalResult> ChangeAsync(Guid workspaceId,Guid id,Guid userId,string op,CancellationToken ct){if(!await Member(workspaceId,userId,ct))return new(FinancialGoalAccess.NotFound,null,null);var g=await repository.FindAsync(workspaceId,id,ct);if(g is null)return new(FinancialGoalAccess.NotFound,null,null);try{var n=time.GetUtcNow();if(op=="pause")g.Pause(n);else if(op=="resume")g.Resume(n);else if(op=="complete")g.Complete(n);else g.Archive(n);await repository.SaveAsync(ct);return new(FinancialGoalAccess.Allowed,await repository.GetAsync(workspaceId,id,ct),null);}catch(InvalidOperationException ex){return new(FinancialGoalAccess.Conflict,null,null,ex.Message);}}
    private static (FinancialGoalDetails?,Dictionary<string,string[]>) Validate(FinancialGoalInput i){var e=new Dictionary<string,string[]>();var n=i.Name?.Trim()??string.Empty;if(n.Length==0)e["name"]=["Informe o nome do objetivo."];else if(n.Length>FinancialGoal.NameMaxLength)e["name"]=["O nome do objetivo excede o limite."];var d=string.IsNullOrWhiteSpace(i.Description)?null:i.Description.Trim();if(d is{Length:>FinancialGoal.DescriptionMaxLength})e["description"]=["A descrição excede o limite."];if(!Enum.TryParse<FinancialGoalType>(i.GoalType,true,out var type))e["goalType"]=["Tipo de objetivo inválido."];if(!Enum.TryParse<FinancialGoalPriority>(i.Priority,true,out var priority))e["priority"]=["Prioridade inválida."];decimal amount=0;if(string.IsNullOrWhiteSpace(i.TargetAmount)||!decimal.TryParse(i.TargetAmount,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out amount)||amount<=0||Money.Validate(amount,"O valor") is not null)e["targetAmount"]=["Informe um valor positivo com até duas casas."];if(e.Count>0)return(null,e);return(new FinancialGoalDetails(n,d,type,amount,i.TargetDate,priority),e);}
    private async Task<bool> Member(Guid workspaceId,Guid userId,CancellationToken ct)=>await workspaces.GetOwnerRoleAsync(workspaceId,userId,ct) is not null;
}
